{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"City of Los Angeles Just Cause for Eviction Ordinance (JCO)","requirement":"A landlord may terminate a tenancy only for listed just causes, which are at-fault reasons (such as nonpayment, lease violation, nuisance or illegal use) or no-fault reasons (such as owner move-in, demolition or a government order to vacate). No-fault evictions require relocation assistance.","key_value":null,"coverage_conditions":"Most residential rental properties in the City of Los Angeles that are not regulated by the City's Rent Stabilization Ordinance; the tenant must have lived in the unit at least six months or the original lease must have expired.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Most residential rentals not regulated by the City's RSO; can apply to buildings newer than October 1, 1978 and to a property with a single single-family dwelling."},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate arrangements, cooperatives under certain circumstances, some non-profit homeless or short-term substance-abuse treatment facilities, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"citation":"Los Angeles Just Cause for Eviction Ordinance (JCO)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"Covers units not regulated by the City's Rent Stabilization Ordinance; the JCO does not regulate rent increases.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Non-payment eviction threshold tied to Fair Market Rent (RSO and JCO units)","requirement":"A landlord may not evict a tenant for falling behind in rent unless the amount owed is higher than the Fair Market Rent for the unit's bedroom size.","key_value":"amount owed must exceed the Fair Market Rent for the unit size","coverage_conditions":"Applies to all RSO and JCO rental units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"RSO and JCO rental units in the City of Los Angeles"},"exemptions":null,"penalty":null,"effective_date":"2023-03-27","citation":"Just Cause For Eviction Ordinance (JCO) – LAHD","quoted_span":"Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR).","interaction":"Applies to all RSO and JCO rental units.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) annual rent increase cap","requirement":"For covered units, annual rent increases may not exceed 5% plus the regional cost-of-living change, or 10%, whichever is lower. The maximum allowable increase was 8.9% from August 1, 2024 to July 31, 2025.","key_value":"5% + CPI, max 10%; 8.9% (Aug 1, 2024 – Jul 31, 2025)","coverage_conditions":"Rental units more than 15 years old, measured on a rolling basis; the page lists exclusions such as newer units, deed-restricted affordable units, certain dormitories, owner-occupied two-unit properties and qualifying single-family homes and condominiums.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"Coverage turns on a rolling 15-year construction cutoff; single-family homes and condominiums are exempt only if not owned by a real estate trust, corporation or LLC with a corporate member and the landlord gave the required written notice."},"exemptions":"Units built within the last 15 years; deed-restricted affordable units; certain dormitories; two-unit properties whose second unit was owner-occupied for the tenancy; qualifying single-family homes and condominiums; units already subject to the City's RSO.","penalty":null,"effective_date":"2024-08-01","citation":"AB 1482 (Cal. Civ. Code § 1947.12)","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":"The City's JCO does not regulate rent increases; AB 1482 may regulate rent in buildings older than 15 years.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
